/*
 * prog24_query_string_parser.c
 *
 * Reads a line from stdin, parses it as a URL‑encoded query string
 * (key=value pairs separated by '&'), decodes each key and value and
 * prints them as “key=value” on separate lines.
 *
 * If no line can be read, prints the literal string “NO_INPUT”.
 *
 * The decoding follows the usual rules:
 *   '+'  -> space
 *   %XX  -> byte with hexadecimal value XX
 *   any other character is copied unchanged.
 *
 * This implementation matches the behaviour of the original binary
 * (the decompiled state‑machine in the provided Ghidra project).
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* ------------------------------------------------------------------ */
/* URL‑decode a NUL‑terminated string.  The result is written to dst.   */
/* dst must be large enough to hold the decoded string (including NUL).*/
/* ------------------------------------------------------------------ */
static void url_decode(const char *src, char *dst)
{
    while (*src) {
        if (*src == '+') {
            *dst++ = ' ';
            src++;
        } else if (*src == '%' && isxdigit((unsigned char)src[1]) && isxdigit((unsigned char)src[2])) {
            /* Convert the two hex digits after '%' */
            char hi = src[1];
            char lo = src[2];
            int val = (isdigit((unsigned char)hi) ? hi - '0' : (tolower((unsigned char)hi) - 'a' + 10));
            val = (val << 4) + (isdigit((unsigned char)lo) ? lo - '0' : (tolower((unsigned char)lo) - 'a' + 10));
            *dst++ = (char)val;
            src += 3;
        } else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Buffers – sizes are generous enough for the test data */
    static char line[2048];
    static char key[1024];
    static char val[1024];

    /* Read a line from stdin */
    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* Strip trailing newline and/or carriage‑return */
    size_t len = strlen(line);
    while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
        line[--len] = '\0';
    }

    /* Parse the query string */
    char *p = line;
    while (*p) {
        char *pair = p;
        char *amp = strchr(p, '&');
        if (amp) {
            *amp = '\0';
            p = amp + 1;          /* start of next pair */
        } else {
            p = "";               /* no more pairs */
        }

        char *eq = strchr(pair, '=');
        if (eq) {
            *eq = '\0';
            url_decode(pair, key);
            url_decode(eq + 1, val);
        } else {
            /* No '=', treat whole token as a key with empty value */
            url_decode(pair, key);
            val[0] = '\0';
        }

        printf("%s=%s\n", key, val);
    }

    return 0;
}
